import logging

from taf.collectors.core import NamedComponentFactory
from taf.collectors.core.entities.local_executor import LocalExecutor
from taf.collectors.core.factories.collector_factory import (
    CoamSbtsCollectorFactory, CoamCUCollectorFactory, VduCollectorFactory)
from taf.collectors.core.factories.factory import Factory
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.pmcounters.collector import (CoamPmCounterCollector,
                                                 CoamVCUPmCounterCollector,
                                                 CoamVDUPmCounterCollector)
from taf.collectors.pmcounters.pmsetupentryfilter import PMSetupEntryFilter

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class PmCollectorFactoryBase(object):

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(PmCollectorFactoryBase, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        if ("for_last" in configuration) or ("intervals" in configuration):
            resulting_arguments["pmsetup_filter"] = PMSetupEntryFilter(
                local_executor=LocalExecutor(),
                for_last=configuration.get("for_last"),
                intervals=configuration.get("intervals"))


class SbtsPmCollectorFactory(PmCollectorFactoryBase,
                             CoamSbtsCollectorFactory,
                             Creating("local_executor", "LocalExecutor"),
                             NamedComponentFactory):
    """
        Factory to create a cOAM admin cli based CoamPmCounterCollector .
    """
    _optional_parameters = {"timeout"}
    _product_class = CoamPmCounterCollector


class CoamVCUPmCollectorFactory(PmCollectorFactoryBase,
                                CoamCUCollectorFactory,
                                Creating("local_executor", "LocalExecutor"),
                                Creating("file_getter", "LocalFileGetter"),
                                NamedComponentFactory):
    """
        Factory to create a CoamCU PM counter collector
    """
    _optional_parameters = {"timeout"}
    _product_class = CoamVCUPmCounterCollector


class CoamVDUPmCollectorFactory(PmCollectorFactoryBase,
                                VduCollectorFactory,
                                Creating("local_executor", "LocalExecutor"),
                                Creating("file_getter", "LocalFileGetter"),
                                NamedComponentFactory):
    """
        Factory to create a CoamVDU PM counter collector
    """
    _optional_parameters = {"timeout"}
    _product_class = CoamVDUPmCounterCollector


_factory_classes = {
    'sbts': SbtsPmCollectorFactory,
    'coam_vcu': CoamVCUPmCollectorFactory,
    'coam_vdu': CoamVDUPmCollectorFactory}


class PmCounterCollectorFactorySelector(Factory):
    def create(self, configuration, existing_arguments):
        oam_type = configuration.pop("oam_type", "sbts")

        return _factory_classes[str(oam_type)]().create(
            configuration=configuration,
            existing_arguments=existing_arguments)
